const int max_iterations_base = 64;
const vec2 center = vec2(-2,-0.5);


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    bool glow = getBool(glowToggle);
    float zoom = getFloat(zoomValue);
    int max_iterations = int(float(max_iterations_base) * log(zoom + 1.0));

    float mag = zoom;

    float ar = iResolution.x / iResolution.y;
    vec2 uv = fragCoord / iResolution.xy * vec2(ar, 1.0);

    vec2 mouse = getVec2(dragOffset);

	//vec2 c = center + uv / mag - mouse;
