const int dragIndex = 1;
const int dragPosition = 2;
const int dragOffset = 3;

const int glowToggle = 4;

const int zoomValue = 6;


int mandelbrot(vec2 c, float mag, vec2 offset, int iterations) {

    uint c_r[ARRAY_SIZE];
    uint c_i[ARRAY_SIZE];
    uint z_r[ARRAY_SIZE];
    uint z_i[ARRAY_SIZE];

    load(c_r, c.x);
    load(c_i, c.y);
    zero(z_r);
    zero(z_i);

    {
        uint tmp[ARRAY_SIZE];
        uint o_r[ARRAY_SIZE];
        uint o_i[ARRAY_SIZE];
        load(o_r, mag);
        load(o_i, mag);
        mul(c_r, o_r, tmp);
        assign(c_r, tmp);
        mul(c_i, o_i, tmp);
        assign(c_i, tmp);
        load(o_r, offset.x);
        load(o_i, offset.y);
        add(c_r, o_r, tmp);
        assign(c_r, tmp);
        add(c_i, o_i, tmp);
        assign(c_i, tmp);
    }

    uint nz_r[ARRAY_SIZE];
    uint nz_i[ARRAY_SIZE];

    for (int k = 0; k < iterations; k++) {

        uint tmp[ARRAY_SIZE];
        uint radius[ARRAY_SIZE];
        mul(z_r, z_r, tmp);
        mul(z_i, z_i, radius);
        add(radius, tmp, radius);

        if (radius[1] > 4u) {
            return k;
        }

        mul(z_i, z_i, nz_r);
        negate(nz_r);
        mul(z_r, z_r, tmp);
        add(nz_r, tmp, nz_r);
        add(nz_r, c_r, nz_r);

        load(nz_i, 2.0);
        mul(nz_i, z_r, nz_i);
        mul(nz_i, z_i, nz_i);
        add(nz_i, c_i, nz_i);

        assign(z_r, nz_r);
        assign(z_i, nz_i);

    }

    return iterations;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int index = toIndex(fragCoord);

    fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0).rgba;

    bool reset = texelFetch(iChannel1, ivec2(82, 1), 0).x > 0.;
    if (reset || iFrame == 0) {
            store(index, dragOffset, setVec2(vec2(0.0, 0.0)));
            store(index, zoomValue, setFloat(1.0));
            store(index, glowToggle, setBool(true));
            return;
    }

    bool mouseDrag = iMouse.z > 0.0;

    bool shift = texelFetch(iChannel1, ivec2(16, 0), 0).x > 0.;
    bool toggle = texelFetch(iChannel1, ivec2(65, 1), 0).x > 0.;
    if (toggle)
    {
        bool glow = getBool(glowToggle);
        store(index, glowToggle, setBool(!glow));
    }

    if (mouseDrag) {
        vec2 mousePos = iMouse.xy / iResolution.y;
        int prevDragIndex = getInt(dragIndex);

        if (prevDragIndex == -1) {
            store(index, dragIndex, setInt(1));
        } else {
            vec2 prevDragPos = getVec2(dragPosition);
            float prevZoom = getFloat(zoomValue);
            vec2 mouseDelta = mousePos - prevDragPos;
            if (shift) {
                float newZoom = prevZoom;
                if (prevZoom > 1.)
                {
                    mouseDelta *= prevZoom;
                }
                if (mouseDelta.x > 0.) {
                    newZoom += mouseDelta.x;
                } else {
                    newZoom += mouseDelta.x;
                }
                newZoom = max(0.1f, newZoom);
                store(index, zoomValue, setFloat(newZoom));
            } else {
                vec2 prevOffset = getVec2(dragOffset);
                if (prevZoom != 0.)
                {
                    mouseDelta /= prevZoom;
                }
                vec2 newOffset = prevOffset + mouseDelta;

                store(index, dragOffset, setVec2(newOffset));
            }
        }

        store(index, dragPosition, setVec2(mousePos));
    } else {
        store(index, dragIndex, setInt(-1));
    }

}
